-- Synthetic disposable/rolled-back fixtures only. Never targets an existing owner.
begin;
create function pg_temp.expect(ok boolean,label text)returns void language plpgsql as $$begin
 if ok is not true then raise exception 'FAIL: %',label;end if;
 perform set_config('folio.data_checks',(coalesce(nullif(current_setting('folio.data_checks',true),''),'0')::int+1)::text,true);
end$$;
create function pg_temp.deny(statement text,label text)returns void language plpgsql as $$begin
 begin execute statement;exception when others then
  if sqlstate<>'42501' then raise exception 'FAIL: % expected permission failure, got %: %',label,sqlstate,sqlerrm;end if;
  perform pg_temp.expect(true,label);return;
 end;raise exception 'FAIL: % accepted',label;
end$$;
with u as(insert into auth.users(id,email,email_confirmed_at)values(gen_random_uuid(),'data-a@example.invalid',now())returning id)select set_config('folio.data_a',id::text,true)from u;
with u as(insert into auth.users(id,email,email_confirmed_at)values(gen_random_uuid(),'data-b@example.invalid',now())returning id)select set_config('folio.data_b',id::text,true)from u;
with s as(insert into auth.sessions(id,user_id)values(gen_random_uuid(),current_setting('folio.data_a')::uuid)returning id)select set_config('folio.data_session',id::text,true)from s;
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('folio.data_a'),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('folio.data_a'),'role','authenticated','is_anonymous',false,'session_id',current_setting('folio.data_session'),'amr',jsonb_build_array(jsonb_build_object('method','password','timestamp',floor(extract(epoch from now())))))::text,true);
select set_config('folio.data_claims',current_setting('request.jwt.claims'),true);
select public.initialize_workspace();
update public.profiles set tracking_start_date=null where id=current_setting('folio.data_a')::uuid;
with a as(insert into public.accounts(name,type,opening_balance_paise,opening_date)values('Synthetic export bank','bank',500000,folio_private.today()-60)returning id)select set_config('folio.data_bank',id::text,true)from a;
select set_config('folio.data_cat',(select id::text from public.categories where kind='expense' limit 1),true);
select public.record_entry(current_setting('folio.data_bank')::uuid,current_setting('folio.data_cat')::uuid,'expense',10029,folio_private.today()-30,'Synthetic earlier expense',null,gen_random_uuid());
update public.profiles set tracking_start_date=folio_private.today() where id=current_setting('folio.data_a')::uuid;
with l as(insert into public.loans(name,principal_paise,apr,tenure_months)values('Synthetic export loan',50000,12,12)returning id)select set_config('folio.data_loan',id::text,true)from l;
select public.record_loan_payment(current_setting('folio.data_loan')::uuid,current_setting('folio.data_bank')::uuid,1000,100,folio_private.today(),'Synthetic linked repayment',gen_random_uuid());
insert into public.statement_rules(account_id,recipient_key,recipient_name,direction,kind)values(current_setting('folio.data_bank')::uuid,'synthetic-rule','Synthetic recipient','debit','exclude');
select set_config('folio.data_export',public.export_financial_data()::text,true);
select pg_temp.expect(current_setting('folio.data_export')::jsonb->>'owner_id'=current_setting('folio.data_a'),'export owner is caller');
select pg_temp.expect(jsonb_array_length(current_setting('folio.data_export')::jsonb->'data'->'transactions')=2,'export includes earlier rows outside report cutoff');
select pg_temp.expect((select count(*)=2 from public.transactions),'export leaves ledger unchanged');
select pg_temp.expect((select bool_and(jsonb_typeof(r->'amount_paise')='string') from jsonb_array_elements(current_setting('folio.data_export')::jsonb->'data'->'transactions')r),'money exported as exact paise strings');
select pg_temp.expect(folio_private.portable_json('{"nested":[{"amount_paise":10029,"note":"Synthetic"}]}')->'nested'->0->>'amount_paise'='10029','nested paise preserved');
select pg_temp.expect((select count(*)=21 from jsonb_object_keys(current_setting('folio.data_export')::jsonb->'data')),'all explicit public financial tables included');
select pg_temp.expect(not(current_setting('folio.data_export')::jsonb->'data' ?| array['auth_users','sessions','mutation_receipts']),'auth/credential/internal tables excluded');
select set_config('request.jwt.claim.sub',current_setting('folio.data_b'),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('folio.data_b'),'role','authenticated','is_anonymous',false)::text,true);
select public.initialize_workspace();
select pg_temp.expect(jsonb_array_length(public.export_financial_data()->'data'->'transactions')=0,'other owner cannot export ledger');
select pg_temp.expect(jsonb_array_length(public.export_financial_data()->'data'->'accounts')=0,'other owner cannot export accounts');
select pg_temp.deny('select public.delete_own_account(''DELETE MY ACCOUNT'')','missing fresh password denied');
select set_config('request.jwt.claim.sub',current_setting('folio.data_a'),true);
select set_config('request.jwt.claims',current_setting('folio.data_claims'),true);
select pg_temp.deny('select public.delete_own_account(''delete my account'')','exact typed confirmation required');
select set_config('request.jwt.claims',jsonb_set(current_setting('folio.data_claims')::jsonb,'{amr}',jsonb_build_array(jsonb_build_object('method','password','timestamp',floor(extract(epoch from now()))-301)))::text,true);
select pg_temp.deny('select public.delete_own_account(''DELETE MY ACCOUNT'')','stale password proof denied');
select set_config('request.jwt.claims',jsonb_set(current_setting('folio.data_claims')::jsonb,'{amr}',jsonb_build_array(jsonb_build_object('method','password','timestamp',floor(extract(epoch from now()))+30)))::text,true);
select pg_temp.deny('select public.delete_own_account(''DELETE MY ACCOUNT'')','future password proof denied');
select set_config('request.jwt.claims',jsonb_set(jsonb_set(current_setting('folio.data_claims')::jsonb,'{amr}','[{"method":"recovery","timestamp":0}]'),'{user_metadata}',jsonb_build_object('amr',jsonb_build_array(jsonb_build_object('method','password','timestamp',floor(extract(epoch from now()))))))::text,true);
select pg_temp.deny('select public.delete_own_account(''DELETE MY ACCOUNT'')','editable metadata cannot prove password');
select set_config('request.jwt.claims',jsonb_set(current_setting('folio.data_claims')::jsonb,'{session_id}',to_jsonb(gen_random_uuid()::text))::text,true);
select pg_temp.deny('select public.delete_own_account(''DELETE MY ACCOUNT'')','missing active session denied');
select set_config('request.jwt.claims',current_setting('folio.data_claims'),true);
reset role;
update auth.sessions set not_after=now()-interval '1 minute' where id=current_setting('folio.data_session')::uuid;
set local role authenticated;
select pg_temp.deny('select public.delete_own_account(''DELETE MY ACCOUNT'')','expired session denied');
reset role;
update auth.sessions set not_after=null where id=current_setting('folio.data_session')::uuid;
set local role authenticated;
select pg_temp.expect(public.delete_own_account('DELETE MY ACCOUNT'),'confirmed synthetic account deleted');
reset role;
select pg_temp.expect(not exists(select 1 from auth.users where id=current_setting('folio.data_a')::uuid),'own Auth user removed');
select pg_temp.expect(not exists(select 1 from auth.sessions where id=current_setting('folio.data_session')::uuid),'own sessions removed');
select pg_temp.expect(exists(select 1 from auth.users where id=current_setting('folio.data_b')::uuid),'other Auth user untouched');
do $$declare t text;n bigint;begin
 foreach t in array array['accounts','categories','transactions','loans','loan_payments','subscriptions','budgets','savings_goals','goal_allocations','loan_document_details','saved_simulations','investment_holdings','investment_entries','statement_rules'] loop
  execute format('select count(*) from public.%I where user_id=$1',t)into n using current_setting('folio.data_a')::uuid;
  perform pg_temp.expect(n=0,'deleted owner cleared from '||t);
 end loop;
end$$;
select pg_temp.expect(not exists(select 1 from folio_private.mutation_receipts where user_id=current_setting('folio.data_a')::uuid),'internal retry receipts removed');
set local role authenticated;
select pg_temp.deny('select public.delete_own_account(''DELETE MY ACCOUNT'')','deleted token cannot delete again');
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('folio.data_b'),'is_anonymous',true)::text,true);
select pg_temp.deny('select public.export_financial_data()','anonymous JWT cannot export');
select pg_temp.deny('select public.delete_own_account(''DELETE MY ACCOUNT'')','anonymous JWT cannot delete');
reset role;
select pg_temp.expect(not has_function_privilege('anon','public.export_financial_data()','execute'),'anonymous export grant absent');
select pg_temp.expect(not has_function_privilege('anon','public.delete_own_account(text)','execute'),'anonymous delete grant absent');
select current_setting('folio.data_checks')||' data control assertions passed';
rollback;
